questionvariables.text:
/* Randomize intercepts to ensure clean integer slopes (m = -c / x_int) */
c : rand([-6, -4, -2, 2, 4, 6]);
x_int : if abs(c)=6 then rand([-3, -2, 2, 3]) else rand([-2, 2]);

m : -c / x_int;

/* Let Maxima handle the algebraic formatting of the equation natively */
line_expr : m*x + c;

/* Determine graph style and shading randomly */
is_solid : rand([true, false]);
is_above : rand([true, false]);

/* Variables passed to JSXGraph */
is_solid_js : if is_solid then 1 else 0;
is_above_js : if is_above then 1 else 0;

/* Define target answers */
ta1 : c;
ta2 : m;

/* Carefully assemble the target inequality based on randomized rules */
ta3_ge : y >= m*x + c;
ta3_g  : y > m*x + c;
ta3_le : y <= m*x + c;
ta3_l  : y < m*x + c;

ta3 : if is_above then (if is_solid then ta3_ge else ta3_g) else (if is_solid then ta3_le else ta3_l);

/* Text string variables for the worked solution */
style_str : if is_solid then "solid" else "dashed";
inclusive_str : if is_solid then "inclusive" else "exclusive (strict)";
symbol_opt1 : if is_solid then "\\le" else "&lt;";
symbol_opt2 : if is_solid then "\\ge" else "&gt;";
region_str : if is_above then "above" else "below";
value_str : if is_above then "greater" else "less";
final_symbol : if is_above then (if is_solid then "\\ge" else "&gt;") else (if is_solid then "\\le" else "&lt;");
